\centering
\caption{Sign misattribution verification ($h{=}2$). Credit agreement = fraction of windows where advantage sign matches local quality; 50\% = random.}
\label{tab:sign_verification}
\small
\begin{tabular}{@{}lcc@{}}
\toprule
